1	package com.loja.checkout;
2	
3	import com.loja.checkout.clube.NivelClube;
4	import com.loja.checkout.clube.RegistroClube;
5	import com.loja.checkout.comum.Dinheiro;
6	import com.loja.checkout.comum.PedidoRecusadoException;
7	import com.loja.checkout.cupom.Cupom;
8	import com.loja.checkout.cupom.CupomContexto;
9	import com.loja.checkout.cupom.RegistroCupons;
10	import com.loja.checkout.entrega.ModalidadeEntrega;
11	import com.loja.checkout.entrega.RegistroEntregas;
12	import com.loja.checkout.pagamento.FormaPagamento;
13	import com.loja.checkout.pagamento.RegistroPagamentos;
14	import com.loja.checkout.pagamento.ResultadoPagamento;
15	import com.loja.checkout.pedido.ItemPedido;
16	import com.loja.checkout.regiao.Regiao;
17	import com.loja.checkout.web.ResumoRequest;
18	import com.loja.checkout.web.ResumoResponse;
19	import org.springframework.stereotype.Service;
20	
21	import java.math.BigDecimal;
22	import java.util.ArrayList;
23	import java.util.List;
24	
25	/**
26	 * Calcula o resumo da compra. Aqui mora o que é igual a todo pedido: a ordem do
27	 * cálculo e a ordem das validações. O que varia por caso (entrega, cupom, nível,
28	 * pagamento) é resolvido por lookup nos registros e delegado a cada caso.
29	 */
30	@Service
31	public class CalculadoraResumo {
32	
33	    private final RegistroEntregas entregas;
34	    private final RegistroCupons cupons;
35	    private final RegistroClube clube;
36	    private final RegistroPagamentos pagamentos;
37	
38	    public CalculadoraResumo(RegistroEntregas entregas, RegistroCupons cupons,
39	                             RegistroClube clube, RegistroPagamentos pagamentos) {
40	        this.entregas = entregas;
41	        this.cupons = cupons;
42	        this.clube = clube;
43	        this.pagamentos = pagamentos;
44	    }
45	
46	    public ResumoResponse calcular(ResumoRequest req) {
47	        // 1. Itens válidos -> subtotal e peso.
48	        List<ItemPedido> itens = validarItens(req.itens());
49	        BigDecimal subtotal = Dinheiro.centavos(somaTotalItens(itens));
50	        BigDecimal peso = somaPesoItens(itens);
51	
52	        // 2. Nível do clube.
53	        NivelClube nivel = clube.buscar(req.nivelClube())
54	                .orElseThrow(() -> new PedidoRecusadoException("NIVEL_CLUBE_INVALIDO"));
55	
56	        // 3. Região.
57	        Regiao regiao = Regiao.porNome(req.regiao())
58	                .orElseThrow(() -> new PedidoRecusadoException("REGIAO_INVALIDA"));
59	
60	        // 4. Modalidade de entrega.
61	        ModalidadeEntrega modalidade = entregas.buscar(req.modalidadeEntrega())
62	                .orElseThrow(() -> new PedidoRecusadoException("MODALIDADE_INVALIDA"));
63	
64	        // 5. Modalidade atende o pedido?
65	        if (!modalidade.atende(peso)) {
66	            throw new PedidoRecusadoException("MODALIDADE_INDISPONIVEL");
67	        }
68	
69	        // Frete exibido: OURO (ou quem tenha frete grátis) zera o frete.
70	        BigDecimal frete = nivel.freteGratis() ? Dinheiro.ZERO : modalidade.frete(peso);
71	
72	        // 6 e 7. Cupom (ausente = sem cupom).
73	        BigDecimal descontoCupom = Dinheiro.ZERO;
74	        if (temCupom(req.cupom())) {
75	            Cupom cupom = cupons.buscar(req.cupom())
76	                    .orElseThrow(() -> new PedidoRecusadoException("CUPOM_INVALIDO"));
77	            CupomContexto ctx = new CupomContexto(subtotal, frete, itens);
78	            if (!cupom.aplicavel(ctx)) {
79	                throw new PedidoRecusadoException("CUPOM_NAO_APLICAVEL");
80	            }
81	            descontoCupom = cupom.desconto(ctx);
82	        }
83	
84	        // Seguro: percentual da região sobre os produtos (sem desconto e sem frete).
85	        BigDecimal seguro = Dinheiro.centavos(subtotal.multiply(regiao.percentualSeguro()));
86	
87	        // Total do pedido.
88	        BigDecimal totalPedido = Dinheiro.centavos(
89	                subtotal.subtract(descontoCupom).add(frete).add(seguro));
90	
91	        // 8. Forma de pagamento.
92	        FormaPagamento forma = pagamentos.buscar(req.formaPagamento())
93	                .orElseThrow(() -> new PedidoRecusadoException("FORMA_PAGAMENTO_INVALIDA"));
94	
95	        // 9. Parcelas permitidas (ausente = 1).
96	        int parcelas = req.parcelas() == null ? 1 : req.parcelas();
97	        if (!forma.parcelasPermitidas(parcelas)) {
98	            throw new PedidoRecusadoException("PARCELAMENTO_INVALIDO");
99	        }
100	
101	        // 10. Forma atende o pedido?
102	        if (!forma.atende(totalPedido)) {
103	            throw new PedidoRecusadoException("FORMA_PAGAMENTO_INDISPONIVEL");
104	        }
105	
106	        // Ajuste do pagamento sobre o total.
107	        ResultadoPagamento pagamento = forma.calcula(totalPedido, parcelas);
108	        BigDecimal ajuste = Dinheiro.centavos(pagamento.valorFinal().subtract(totalPedido));
109	
110	        return new ResumoResponse(
111	                subtotal,
112	                descontoCupom,
113	                frete,
114	                modalidade.prazoDias(),
115	                seguro,
116	                ajuste,
117	                pagamento.valorFinal(),
118	                parcelas,
119	                pagamento.valorParcela(),
120	                nivel.credito(subtotal),
121	                nivel.brinde(subtotal));
122	    }
123	
124	    private List<ItemPedido> validarItens(List<ResumoRequest.Item> itens) {
125	        if (itens == null || itens.isEmpty()) {
126	            throw new PedidoRecusadoException("PEDIDO_INVALIDO");
127	        }
128	        List<ItemPedido> validos = new ArrayList<>();
129	        for (ResumoRequest.Item item : itens) {
130	            if (item == null
131	                    || naoPositivo(item.precoUnitario())
132	                    || item.quantidade() == null || item.quantidade() <= 0
133	                    || naoPositivo(item.pesoKg())) {
134	                throw new PedidoRecusadoException("PEDIDO_INVALIDO");
135	            }
136	            validos.add(new ItemPedido(item.nome(), item.precoUnitario(),
137	                    item.quantidade(), item.pesoKg()));
138	        }
139	        return validos;
140	    }
141	
142	    private boolean naoPositivo(BigDecimal valor) {
143	        return valor == null || valor.compareTo(BigDecimal.ZERO) <= 0;
144	    }
145	
146	    private BigDecimal somaTotalItens(List<ItemPedido> itens) {
147	        BigDecimal soma = BigDecimal.ZERO;
148	        for (ItemPedido item : itens) {
149	            soma = soma.add(item.totalLinha());
150	        }
151	        return soma;
152	    }
153	
154	    private BigDecimal somaPesoItens(List<ItemPedido> itens) {
155	        BigDecimal soma = BigDecimal.ZERO;
156	        for (ItemPedido item : itens) {
157	            soma = soma.add(item.pesoLinha());
158	        }
159	        return soma;
160	    }
161	
162	    private boolean temCupom(String cupom) {
163	        return cupom != null && !cupom.isBlank();
164	    }
165	}
