1	package com.loja.checkout.pagamento;
2	
3	import com.loja.checkout.comum.Dinheiro;
4	import org.springframework.stereotype.Component;
5	
6	import java.math.BigDecimal;
7	import java.math.RoundingMode;
8	
9	/**
10	 * Cartão de crédito de 1 a 12 vezes. Até 3x sem juros (valor final = total);
11	 * de 4x a 12x com juros de 1,99% ao mês pela tabela Price.
12	 */
13	@Component
14	public class CartaoPagamento implements FormaPagamento {
15	
16	    private static final int MAX_PARCELAS = 12;
17	    private static final int MAX_SEM_JUROS = 3;
18	    private static final BigDecimal TAXA = new BigDecimal("0.0199");
19	    private static final int ESCALA_CALCULO = 12;
20	
21	    @Override
22	    public String codigo() {
23	        return "CARTAO";
24	    }
25	
26	    @Override
27	    public boolean parcelasPermitidas(int parcelas) {
28	        return parcelas >= 1 && parcelas <= MAX_PARCELAS;
29	    }
30	
31	    @Override
32	    public boolean atende(BigDecimal totalPedido) {
33	        return true;
34	    }
35	
36	    @Override
37	    public ResultadoPagamento calcula(BigDecimal totalPedido, int parcelas) {
38	        if (parcelas <= MAX_SEM_JUROS) {
39	            BigDecimal parcela = totalPedido.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
40	            return new ResultadoPagamento(Dinheiro.centavos(totalPedido), parcela);
41	        }
42	        BigDecimal parcela = parcelaComJuros(totalPedido, parcelas);
43	        BigDecimal valorFinal = Dinheiro.centavos(parcela.multiply(BigDecimal.valueOf(parcelas)));
44	        return new ResultadoPagamento(valorFinal, parcela);
45	    }
46	
47	    // Tabela Price: parcela = total * i / (1 - (1 + i)^-n).
48	    // Reescrito com potência inteira: parcela = total * i * p / (p - 1), p = (1 + i)^n.
49	    private BigDecimal parcelaComJuros(BigDecimal total, int parcelas) {
50	        BigDecimal p = BigDecimal.ONE.add(TAXA).pow(parcelas);
51	        BigDecimal numerador = total.multiply(TAXA).multiply(p);
52	        BigDecimal denominador = p.subtract(BigDecimal.ONE);
53	        BigDecimal parcela = numerador.divide(denominador, ESCALA_CALCULO, RoundingMode.HALF_EVEN);
54	        return Dinheiro.centavos(parcela);
55	    }
56	}
