3	import java.util.List;
4	import java.util.Map;
5	import java.util.Optional;
6	import java.util.function.Function;
7	import java.util.stream.Collectors;
8	
9	/**
10	 * Escolher um caso é sempre um lookup por código, nunca uma cadeia de condições.
11	 * Esta é a parte igual às quatro famílias; cada registro concreto só diz qual é
12	 * o seu tipo. Opções novas aparecem só adicionando um bean que implementa a
13	 * interface da família — nada aqui muda.
14	 */
15	public abstract class RegistroDeCodigos<T extends Codificavel> {
16	
17	    private final Map<String, T> porCodigo;
18	
19	    protected RegistroDeCodigos(List<T> itens) {
20	        this.porCodigo = itens.stream()
21	                .collect(Collectors.toMap(Codificavel::codigo, Function.identity()));
22	    }
23	
24	    public Optional<T> buscar(String codigo) {
25	        if (codigo == null) {
26	            return Optional.empty();
27	        }
28	        return Optional.ofNullable(porCodigo.get(codigo));
29	    }
30	}
